const cardScoreCalculation = (card: Card, targetRow: Row, roundsRemaining: number): number => {
    let score = 0;

    if (card.immuneAll) { // immune all cards just have their score
        return card.score;
    }

    if (card.estimateFinalScore) {
        score = card.estimateFinalScore(card, roundsRemaining); // estimated final score for cards that do things across rounds
    } else  {
        score = (card.modifiedBaseScore ?? card.score) + (card.bonusScore ?? 0);
    }

    score -= targetRow.rowWeaken;

    score *= targetRow.rowMultiplier; // calculate row multiplier

    if (targetRow.supressed && card.supressionImmune !== true) { // calculate row supression
        score /= 2;
    }

    return score;
}

