import { Card } from "./types";
import { AllCards } from "./AllCards";

class Deck {
    cards: Card[]; // map with card and used or not
    inUseDeck: Card[];

    constructor() {
        this.cards = [];
        this.inUseDeck = [];
    }

    resetInUseDeck(): void {
        this.inUseDeck = [];
        this.cards.forEach(card => {
            card.bonusScore = 0;
            card.calculatedScore = card.score;
            card.modifiedBaseScore = undefined;
            card.roundTrigger = undefined;
            card.triggerEvent = undefined;
            this.inUseDeck.push(card);
        });
    }

    addCard(card: Card): void {
        this.cards.push(card);
    }

    deckRemove(card: Card) {
        const index = this.cards.findIndex(c => c.id === card.id);
        if (index !== -1) {
            this.cards.splice(index, 1);
        }
    }

    inUseDeckRemove(index: number) {
        this.inUseDeck.splice(index, 1);
    }

    getDeck(): Card[] {
        return this.cards;
    }
}

export default Deck;