import { useEffect, useContext, useState, useRef } from 'react';
import '../styles/GameContainer.css';
import { Card, Row as RowType } from './types';
import Row from './Row';
import Hand from './Hand';
import CarddeckContext from './CardContext';
import { RoundContext } from './RoundContext';
import Enemy from './Enemy';
import { useNavigate, useLocation } from 'react-router-dom';
import grassRow from './imgs/grassRow.png';
import bushRow from './imgs/bushRow.png';
import tallRow from './imgs/tallRow.png';

const handSize = 5; // player hand size
const roundsUntilEnd = 10; // round count per game
const enemy = new Enemy(); // enemy AI controller

// init all rows with default values
const rowsDef: RowType[] = Array.from({ length: 6 }, (_, index) => ({
    id: index,
    rowMultiplier: 1,
    rowWeaken: 0,
    supressed: false,
    cards: []
}));

function GameContainer() {
    const navigate = useNavigate();

    // game components:
    const [rows, setRows] = useState<RowType[]>(rowsDef);
    const [hand, setHand] = useState<Card[]>([]);
    const [selectedCard, setSelectedCard] = useState<Card | null>(null);
    const [enemySelectedCard, setEnemySelectedCard] = useState<Card | null>(null);
    const [enemyCardTarget, setEnemyCardTarget] = useState<[number, number] | null>(null);

    // Scores:
    const [enemyScore, setEnemyScore] = useState(0);
    const [enemyDoingTurn, setEnemyDoingTurn] = useState(false);
    const [enemySkippingTurn, setEnemySkippingTurn] = useState(false);
    const [playerScore, setPlayerScore] = useState(0);
    const playerScoreRef = useRef(playerScore);
    const enemyScoreRef = useRef(enemyScore);

    // Win states:
    const [winCardChoices, setWinCardChoices] = useState<Card[] | null>(null);
    const [winCard, setWinCard] = useState<Card | null>(null);
    const [skipWinCard, setSkipWinCard] = useState<boolean>(false);
    
    const [turn, setTurn] = useState(0);
    const [gameWon, setGameWon] = useState<boolean | null>(null);

    // Drag card:
    const [dragCard, setDraggedCard] = useState<Card | null>(null);

    // lock out back button:
    const location = useLocation();
    useEffect(() => {
        window.history.pushState(null, document.title, window.location.href);
        const handleBeforeUnload = (event: Event) => {
            event.preventDefault(); // prevent unload
        };

        const handleBack = (event: Event) => {
            window.history.pushState(null, document.title, window.location.href); // prevent back button
        }

        window.addEventListener('popstate', handleBack);
        window.addEventListener('beforeunload', handleBeforeUnload);

        return () => {
            window.removeEventListener('popstate', handleBack);
            window.removeEventListener('beforeunload', handleBeforeUnload);
        };        
    }, [location]);

    // update score refs:
    useEffect(() => {
        enemyScoreRef.current = enemyScore;
    }, [enemyScore]);

    useEffect(() => {
        playerScoreRef.current = playerScore;
    }, [playerScore]);

    // get deck and total card from deck context:
    const deckContext = useContext(CarddeckContext);

    if (!deckContext) {
        throw new Error('CardContext must be used within a CardProvider');
    }
    
    const { userCards, deck } = deckContext;

    // get current round(level) from round context:
    const roundContext = useContext(RoundContext);

    if (!roundContext) {
        throw new Error('RoundContext must be used within a RoundProvider');
    }

    const { round, setRound } = roundContext;

    // Init/Reset game:
    const initialize = () => {
        // Reset all variables:
        setGameWon(null);
        setTurn(0);
        setPlayerScore(0);
        setEnemyScore(0);
        setSelectedCard(null);
        setEnemySelectedCard(null);

        // reset rows:
        rows.forEach(row => {
            row.rowMultiplier = 1;
            row.supressed = false;
            row.rowWeaken = 0;
            row.cards = [];
        });

        // reset decks:
        deck.resetInUseDeck(); // reset the deck to be drawn from
        if (deck.cards.length === 0) { // if the deck is empty return to deck builder
            navigate('/');
        }
        enemy.generateDeck(round); // reset enemy deck

        // reset hand:
        let tempHand: Card[] = [];
        for (let i = 0; i < handSize; i++) {
            tempHand = drawCard(tempHand);
        }
        setHand(tempHand);
    }

    // initialize on page load:
    useEffect(() => {
        initialize();
    }, []);

    // draw a new random card to the hand:
    const drawCard = (hand: Card[]): Card[] => {
        if (deck.inUseDeck.length === 0) { // deck empty
            return hand;
        }

        const randIndex = Math.floor(Math.random() * deck.inUseDeck.length);
        const newHand = [...hand, deck.inUseDeck[randIndex]];
        deck.inUseDeckRemove(randIndex); // remove drawn card from in use deck
        return newHand;
    }

    // place a card on the screen and start the next turn:
    const placeCard = (card: Card, rowId: number) => {
        if (enemyDoingTurn || gameWon !== null) {
            return;
        }

        // Find the row and add the card to it
        let tempRows = rows.map(row => { // temp rows to be passed along and updated
            if (row.id === rowId) {
                return { ...row, cards: [...row.cards, card] };
            }
            return row;
        });

        card.placedRow = rowId; // updated placed row of the card

        let tempHand = hand.filter(handCard => handCard.id !== card.id); // temp hand to be passed along and updated
        
        // card place actions
        if (card.placeAction) {
            [tempRows, tempHand] = card.placeAction(card, tempRows, tempHand);
        }

        setSelectedCard(null); // Deselect the card after placing it
        nextTurn(tempRows, tempHand);
    };

    // move to next turn and run enemy turn:
    const nextTurn = async (rows: RowType[], hand: Card[]) => {
        let tempRows = [...rows];
        let tempHand = [...hand];

        // run on-round events
        tempRows.forEach(row => {
            row.cards.forEach(card => {
                if (card.onRound && card.placedRow) {
                    [tempRows, tempHand] = card.onRound(turn + 1, card, card.placedRow, tempRows, tempHand);
                }

                if (card.roundTrigger === turn && card.triggerEvent && card.placedRow) {
                    [tempRows, tempHand] = card.triggerEvent(card, card.placedRow, tempRows, tempHand);
                }
            });
        });

        // Draw a new card:
        if (tempHand.length < handSize) {
            tempHand = drawCard(tempHand);
        }

        // Apply all updates in a single state update
        setRows(tempRows);
        setHand(tempHand);  

        // enemy turn
        await enemyTurn(tempRows, tempHand);
        if (roundsUntilEnd-(turn+1) === 0) {
            setEnemyDoingTurn(true); // lock the player out of actions during the end screen delay
            await delay(2000);
            setEnemyDoingTurn(false);
            gameEnd();
        } else {
            setTurn(turn+1);
        }
    }

    const delay = (ms:number) => new Promise(res => setTimeout(res, ms)); // delay function for async

    // async enemy turn, uses delay to prevent actions during and show visibly what its doing
    const enemyTurn = async (rows: RowType[], hand: Card[]) => {
        let tempRows = [...rows];
        setEnemyDoingTurn(true);

        // select enemy card
        let card: Card | null, selectedIndex: number | null, selectedRow: number | null; 
        [card, selectedRow, selectedIndex] = enemy.selectTurnCard(rows, roundsUntilEnd-turn);
        if (card === null) {
            console.log("Enemy skipped turn!");
            // set skipping turn state to display UI showing turn skipped
            setEnemySkippingTurn(true);
            await delay(2000);
            setEnemySkippingTurn(false);
            setEnemyDoingTurn(false);
            return;
        }

        if (card.selectsOtherCards === true) { // to highlight the card the enemy is targeting
            setEnemyCardTarget([selectedRow || 0, selectedIndex || 0]);
        }
        
        //Update UI state with enemy selection
        setEnemySelectedCard(card);

        //TODO: user can control enemy turn speed?
        await delay(2000); // wait 2 seconds

        tempRows = enemy.useTurnCard(tempRows, card, selectedRow, selectedIndex, turn);
        
        // update states
        setEnemySelectedCard(null);
        setRows([...tempRows]);
        setEnemyCardTarget(null);
        setEnemyDoingTurn(false);
    }

    // cards that select other cards:
    const selectCardAction = (selectedCardIndex: number, rowId: number, card: Card) => {
        if (enemyDoingTurn || gameWon !== null) {
            return;
        }

        let tempRows = [...rows]; // temp rows passed along to be updated
        let tempHand = [...hand]; // temp rows passed along to be updated

        if (card.selectCardAction) {
            [tempRows, tempHand] = card.selectCardAction(card, rowId, selectedCardIndex, tempRows, tempHand, turn);
            setSelectedCard(null); // unselect card
            nextTurn(tempRows, tempHand);
        }
    }

    // select card to display:
    const handleCardSelect = (card: Card) => {
        if (selectedCard && selectedCard.id === card.id) {
            setSelectedCard(null); // Deselect the card if it's clicked again
        } else {
            setSelectedCard(card); // Select the new card
        }
    };

    // game end when turn = the ending turn (10)
    const gameEnd = () => {
        const win = playerScoreRef.current >= enemyScoreRef.current;
        setGameWon(win);
        if (win) {
            const cardChoices = userCards.generateCardChoices(3, round);
            if (cardChoices?.length === 0) {
                setSkipWinCard(true);
            }
            setWinCardChoices(cardChoices);
        }
    }

    // discard a card from the hand:
    const discardCard = (card: Card) => {
        if (enemyDoingTurn) return; // can't discard during enemy turn
        let tempHand = [...hand];
        tempHand = tempHand.filter(c => c.id !== card.id); // remove card from hand
        tempHand = drawCard(tempHand); // draw new card
        setHand(tempHand); // update hand state
        nextTurn(rows, tempHand); // next turn
    }

    // calculate score of all cards in rows if the row or cards change
    const calculateTotalScore = () => {
        let playerScore = 0;
        let enemyScore = 0;

        rows.forEach((row, index) => {
            // update scores
            row.cards.forEach(card => {
                if (card.immuneAll) { // immune all cards have no effects
                    card.calculatedScore = card.score;
                    card.modifiedBaseScore = undefined;
                    card.bonusScore = undefined;
                } else { // other cards
                    // modifiedBaseScore ?? score + bonus - weaken * row multiplier / 2 (if supressed) = calculatedScore 

                    card.calculatedScore = (card.modifiedBaseScore || card.score);

                    if (card.bonusScore) {
                        card.calculatedScore += card.bonusScore;
                    }

                    if (row.rowWeaken && card.rowWeakenImmune !== true) {
                        card.calculatedScore -= row.rowWeaken;
                    }

                    card.calculatedScore *= row.rowMultiplier;

                    if (row.supressed && card.supressionImmune !== true) {
                        card.calculatedScore =  Math.floor(card.calculatedScore/2);
                    }
                }

                if (card.calculatedScore < 0) {
                    card.calculatedScore = 0;
                }

                if (index < 3) { // enemy side
                    enemyScore += card.calculatedScore;
                } else { // player side
                    playerScore += card.calculatedScore;
                }
                
            });
        });

        // score states for UI:
        setPlayerScore(playerScore);
        setEnemyScore(enemyScore);
    };

    // update score any time the rows are changed:
    useEffect(() => { 
        calculateTotalScore();
    }, [rows]);

    // if game won, render game over components:
    const renderGameOverBox = () => {
        if (gameWon !== null) {
            if (gameWon) {
                return (
                    <div className='gameOverBox'>
                        <h1>You Win!!</h1>
                        {!skipWinCard && <h3>Choose a Card:</h3>}
                        <div className="cardSelection">
                            {winCardChoices?.map(card => {
                                return (
                                    <div key={card.id} className={`card ${winCard?.id === card.id ? 'selected' : ''}`} onClick={() => { setWinCard(card) }} style={{ backgroundColor: (card.backgroundColor ?? 'burlywood') }}>
                                        <img src={card.image} alt='Card Icon'></img>
                                        <h4>{card.title}</h4>
                                        {card.specialActionDescription && (
                                            <div className='specialDesc'>
                                                {card.specialActionDescription}
                                            </div>
                                        )}
                                        <div className='placableRows'>{card.rowTargetID?.map((row, index, arr) => {
                                            if (row > 2) {
                                                row = Math.abs(5-row);
                                                if (arr.includes(row)) { // dont do duplicates
                                                    return null;
                                                }
                                            }

                                            return (
                                                <img key={row} className='rowTarget' src={row === 0 ? tallRow : row === 1 ? bushRow : grassRow} alt='rowIndicator'/>
                                            )
                                        })}</div>
                                        <div className='cardScore'>{card.score}</div>
                                    </div>
                                )
                            })}
                        </div>
                        {(winCard !== null || skipWinCard) &&
                            <div className='gameOverBtnContainer'>
                                <button className='updateDeckBtn' onClick={() => {
                                    setRound(round + 1);
                                    if (!skipWinCard) {
                                        userCards.addCard(winCard!);
                                        setWinCard(null);
                                    }
                                    navigate('/');
                                }}>Update Deck</button>
                                <button className='nextTurnBtn' onClick={() => {
                                    setRound(round + 1);
                                    if (!skipWinCard) {
                                        userCards.addCard(winCard!);
                                        setWinCard(null);
                                    }
                                    initialize();
                                }}>Next Round</button>
                            </div>
                        }
                    </div>
                );
            } else {
                return (
                    <div className='gameOverBox'>
                        <h2>You Lose :(</h2>
                        <div className='gameOverBtnContainer'>
                            <button className='updateDeckBtn' onClick={() => navigate('/')}>Update Deck</button>
                            <button className='nextTurnBtn' onClick={() => initialize()}>Try Again</button>
                        </div>
                    </div>
                );
            }
        } else {
            return null;
        }
    }

    return (
        <div id='gameContainer'>
            <div id='gameBody'>
                <div id='sidebar'>
                    <div id="enemyDeckSize">{enemy.getDeck().length}</div>
                    <div id='enemyScore' className='score' style={{backgroundColor: (enemyScore > playerScore) ? '#FFC214' : 'burlywood'}}>{enemyScore}</div>
                    <div id='remainingTurns'>Turn: {turn+1}/{roundsUntilEnd}</div>
                    <div id='playerScore' className='score' style={{backgroundColor: (playerScore > enemyScore) ? '#FFC214' : 'burlywood'}}>{playerScore}</div>
                    <div id="playerDeckSize">{deck.inUseDeck.length}</div>
                </div>
                <div id='playspaceContainer'>
                    {renderGameOverBox()}

                    <div id="levelIndicator">Level: {round}</div>

                    {gameWon === null && rows.map(row => (
                        <Row 
                        key={row.id} 
                        row={row} 
                        dragCard={dragCard}
                        dropDragCard={() => {
                            if (dragCard && !dragCard.selectsOtherCards && dragCard.rowTargetID?.includes(row.id)) {
                                placeCard(dragCard, row.id);
                            }
                        }}
                        dropCardSelect={(cardNum) => {
                            if (dragCard && dragCard.selectsOtherCards === true && dragCard?.rowTargetID?.includes(row.id)) {
                                selectCardAction(cardNum, row.id, dragCard);
                            }
                        }}
                        isHighlighted={(!selectedCard?.selectsOtherCards && !dragCard?.selectsOtherCards) && (selectedCard?.rowTargetID?.includes(row.id) || dragCard?.rowTargetID?.includes(row.id) || false)}
                        cardsHighlighted={(selectedCard?.selectsOtherCards === true || dragCard?.selectsOtherCards === true) && (selectedCard?.rowTargetID?.includes(row.id) || dragCard?.rowTargetID?.includes(row.id) || false)}
                        isCardReady={selectedCard !== null}
                        enemyTarget={enemyCardTarget}
                        onRowClick={() => {
                            if (selectedCard && !selectedCard.selectsOtherCards && selectedCard.rowTargetID?.includes(row.id)) {
                                placeCard(selectedCard, row.id);
                            }
                        }}
                        onCardSelect={(cardNum) => {
                            if (selectedCard && selectedCard.selectsOtherCards === true && selectedCard?.rowTargetID?.includes(row.id)) {
                                selectCardAction(cardNum, row.id, selectedCard);
                                return true;
                            } else {
                                return false;
                            }
                        }}/>
                    ))}

                    {enemySelectedCard !== null &&
                        <div className='card enemy-selected-card' style={{backgroundColor: (enemySelectedCard.backgroundColor ?? 'burlywood')}}>
                            <img src={enemySelectedCard.image} alt='Card Icon'></img>
                            <h4>{enemySelectedCard.title}</h4>
                            {enemySelectedCard.specialActionDescription && (
                                <div className='specialDesc'>
                                    {enemySelectedCard.specialActionDescription}
                                </div>
                            )}
                            <div className='cardScore'>{enemySelectedCard.calculatedScore || enemySelectedCard.score}</div>
                        </div>
                    }

                    {enemySkippingTurn &&
                        <div className='card enemy-selected-card enemy-skip-turn'>
                            <h3>Discarded a Card</h3>
                            <div className='specialDesc'>
                                Enemy turn has been skipped due to discarding a card.
                            </div>
                        </div>
                    }
                </div>
            </div>
            {gameWon === null && 
                <Hand hand={hand} discardCard={discardCard} enemyDoingTurn={enemyDoingTurn} deckSize={deck.inUseDeck.length} setParentDraggedCard={setDraggedCard} onCardSelect={handleCardSelect} selectedCard={selectedCard}/>
            }
        </div>
    );

}

export default GameContainer;