import React, { useState, useEffect, useRef } from 'react';
import { Card, Row as RowType } from './types';
import '../styles/Row.css';
import grassRow from './imgs/grassRow.png';
import bushRow from './imgs/bushRow.png';
import tallRow from './imgs/tallRow.png';

interface RowProps {
  row: RowType; // this row
  isHighlighted: boolean; // if this row is highlighted
  dragCard: Card | null; // the card being dragged
  cardsHighlighted: boolean; // if the cards in this row should be highlighted as selectable
  isCardReady: boolean; // is card ready to place
  enemyTarget: [number, number] | null; // the target of an enemy card
  onRowClick: () => void; // row click event
  dropDragCard: () => void; // drop card in this row event (same effect as row click)
  onCardSelect: (cardId: number) => boolean; // row card clicked
  dropCardSelect: (cardId: number) => void; // card dropped on row card (similar event to onCardSelect)
}

const Row: React.FC<RowProps> = ({ row, isHighlighted, dragCard, dropDragCard, isCardReady, cardsHighlighted, enemyTarget, onRowClick, onCardSelect, dropCardSelect }) => {
    const [displayCard, setDisplayCard] = useState<Card>();
    const rowRef = useRef<HTMLDivElement>(null); // ref to this row
    const cardRefs = useRef<(HTMLDivElement | null)[]>([]); // list of refs to all cards in this row
    
    // set card ref list item:
    const updateRef = (el: HTMLDivElement | null, index: number) => {
        cardRefs.current[index] = el;
    };

    // On row card click:
    const handleCardClick = (card: Card) => {
        if (displayCard && card.id === displayCard.id) { // Remove Display Card
            setDisplayCard(undefined);
            window.removeEventListener('click', windowClickHandler); // Remove the event listener
        } else { // Add display card
            setDisplayCard(card);
            window.addEventListener('click', windowClickHandler);
        }
    }

    // clear currently displayed card if the window is clicked anywhere:
    const windowClickHandler = (event: MouseEvent) => {
        setDisplayCard(undefined);
        window.removeEventListener('click', windowClickHandler); // Remove the event listener
    }

    // Drop effects: 
    useEffect(() => {
        if (!dragCard) return;
        // handle drag and drop into row
        const handleCardDrop = (event: CustomEvent) => {
            if (!dragCard?.selectsOtherCards) { // if card is non-selecting card, call method to place it:
                dropDragCard();
            }

        };

        // handle drag and drop selecting cards
        const handleCardDropCard = (event: CustomEvent) => {
            if (dragCard?.selectsOtherCards) {
                const index = cardRefs.current.findIndex(c => c === event.currentTarget); // get the index of that card in the row
                dropCardSelect(index); // select card at index
            }
        }        
    
        const rowRefCopy = rowRef.current; // copy of the ref as it may change with state updates
        if (rowRefCopy) {
            rowRefCopy.addEventListener('cardDrop', handleCardDrop as EventListener);
        }

        const cardRefsCopy = cardRefs.current; // copy of the current card ref
        for (let ref of cardRefsCopy) { // add event listeners to all cards
            if (ref !== null) {
                ref.addEventListener('cardDrop', handleCardDropCard as EventListener);
            }
        }
        
        return () => {
            if (rowRefCopy) {        
                rowRefCopy.removeEventListener('cardDrop', handleCardDrop as EventListener);
            }

            for (let ref of cardRefsCopy) {
                if (ref !== null) {
                    ref.removeEventListener('cardDrop', handleCardDropCard as EventListener);
                }
            }
        };
    }, [dragCard, row]);

    return (
        <div 
        ref={rowRef} 
        onDragOver={(e) => e.preventDefault()} 
        className={`gameRow ${row.id < 3 ? 'enemyRow' : ''}`} 
        style={{ backgroundColor: isHighlighted ? '#FFC214' : row.supressed ? '#8C92AC' : '', cursor: isHighlighted ? 'pointer' : 'default' }} 
        onClick={onRowClick}>
            <div className='bgIndicator'><img src={(row.id === 0 || row.id === 5) ? tallRow : (row.id === 1 || row.id === 4) ? bushRow : grassRow} alt='row indicator'/></div>
            {row.cards.map((card, index) => (
                <div 
                key={`${row.id}-${index}`} 
                ref={(el) => updateRef(el, index)}
                className={`${displayCard?.id === card.id ? 'rowDisplayCard' : 'rowCard'} ${cardsHighlighted ? 'selectable' : ''} 
                            ${(enemyTarget !== null && enemyTarget[0] === row.id && enemyTarget[1] === index) ? 'targeted' : ''}`}
                style={{backgroundImage: displayCard?.id === card.id ? 'none' : `url(${card.image})`, backgroundColor: (card.backgroundColor ?? 'burlywood')}} 
                onClick={(e) => { // on card click
                    if (!isCardReady) { // stop propagation if a card is not ready to be placed in the row
                        e.stopPropagation();
                    }
                    
                    if (!onCardSelect(index) && !isCardReady) { // no select action happens
                        handleCardClick(card);
                    }
                }}>
                    {displayCard?.id === card.id && <img src={card.image} alt="Card Icon"/>}
                    <div className='rowCardTitle' style={{backgroundColor: card.roundTrigger ? '#FFFF8F' : (card.backgroundColor ?? '#F1F2F3')}}>{card.title}</div>
                    {displayCard?.id === card.id ?
                        <>
                            {card.specialActionDescription && (
                                <div className='specialDesc'>
                                    {card.specialActionDescription}
                                </div>
                            )}

                            {card.roundTrigger && (
                                <div className='triggerDesc'>
                                    Card will trigger event on turn {card.roundTrigger}
                                </div>
                            )}

                            <div className='cardDesc'>
                                <p>{card.description}</p>
                            </div>

                            <div className='scoreBreakdown'>
                                {(row.supressed && displayCard?.supressionImmune !== true) &&
                                    <span>(</span>
                                }
                                
                                {card.modifiedBaseScore ? 
                                    <span style={{color: 'red'}}>{card.modifiedBaseScore}</span>
                                    :
                                    <span>{card.score}</span>
                                }
                                
                                {(card.bonusScore !== undefined && card.bonusScore > 0) &&
                                    <span style={{color: 'green'}}> + {card.bonusScore}</span>
                                }

                                {(row.rowWeaken > 0 && card.rowWeakenImmune !== true) &&
                                    <span style={{color: 'red'}}> - {row.rowWeaken}</span>
                                }

                                {row.rowMultiplier > 1 &&
                                    <span style={{color: 'blue'}}> x {row.rowMultiplier}</span>
                                }
                                {(row.supressed && card.supressionImmune !== true) &&
                                    <><span>)</span><span style={{color: 'red'}}> / 2</span></>
                                }
                                <span> = {card.calculatedScore}</span>
                            </div>
                        </>
                        :
                        <div className='cardScore'>{card.calculatedScore}</div>
                    }
                </div>
            ))}
        </div>
    );
};

export default Row;