import React from 'react';
import { useState, useCallback, useRef, useEffect } from 'react';
import { throttle } from 'lodash';
import { Card as CardType, Row } from './types';
import '../styles/Card.css';
import grassRow from './imgs/grassRow.png';
import bushRow from './imgs/bushRow.png';
import tallRow from './imgs/tallRow.png';

interface HandProps { // Hand Prop Types
    hand: CardType[]; // this hand
    discardCard: (card: CardType) => void; // function to discard a card and draw a new one
    deckSize: number; // current size of the deck
    onCardSelect: (card: CardType) => void; // event on card selection (display the card)
    enemyDoingTurn: boolean; // disable placing cards when enemy is doing turn
    setParentDraggedCard: React.Dispatch<React.SetStateAction<CardType | null>>; // set the dragged card of the game container
    selectedCard: CardType | null; // the currently selected card to display
}

interface HandcardProps {
    card: CardType, // card in hand
    onCardSelect: (card: CardType) => void; // on card select callback
    selectedCard: CardType | null; // current selected card
    draggedCard: CardType | undefined; // currently dragged card
    //Drag and touch events:
    handleDragStart: (e: React.DragEvent<HTMLDivElement>, card: CardType) => void; 
    handleTouchEnd: (e: React.TouchEvent<HTMLDivElement> | React.DragEvent<HTMLDivElement>) => void;
    handleTouchStart: (e: React.TouchEvent<HTMLDivElement>, card: CardType) => void;
    handleTouchMove: (e: React.TouchEvent<HTMLDivElement>) => void;
}

const preventDefault = (e: TouchEvent) => {
    e.preventDefault();
};

const Hand: React.FC<HandProps> = ({ hand, discardCard, enemyDoingTurn, deckSize, onCardSelect, setParentDraggedCard, selectedCard }) => {
    const memoizedPreventDefault = useCallback((e: TouchEvent) => {
        preventDefault(e);
    }, []);

    // Drag states:
    const [draggedCard, setDraggedCard] = useState<CardType>(); // the card being dragged
    const [draggedCardMouse, setDraggedCardMouse] = useState(false); // if it is a mouse drag (true) or a touch drag (false) needed for some properties
    const [touchPosition, setTouchPosition] = useState<{ x: number, y: number } | undefined>(undefined); // finger/mouse position
    const [dragCardPosition, setDragCardPosition] = useState<{ x: number, y: number } | undefined>(undefined); // offest postion for card
    const touchTimeout = useRef<NodeJS.Timeout | null>(null); // timeout for small delay before touch event turns into drag

    // Mouse drag event started
    const handleDragStart = (e: React.DragEvent<HTMLDivElement>, card: CardType) => {
        if (enemyDoingTurn) { // ignore when enemy is doing turn because states can get messed up
            e.preventDefault();
            return;
        }
        // Remove the drag image by setting it to a transparent image:
        const img = new Image();
        img.src = 'data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///ywAAAAAAQABAAACAUwAOw=='; // Transparent image
        e.dataTransfer.setDragImage(img, 0, 0);

        // Set states:
        setDraggedCardMouse(true);
        setDraggedCard(card);
        setParentDraggedCard(card);
        setTouchPosition({ x: e.clientX, y: e.clientY });
        setDragCardPosition({ x: e.clientX - (e.currentTarget.clientWidth / 2), y: e.clientY - (e.currentTarget.clientHeight / 2) });
    };

    // remove touch listeners that disable default controls like the back arrow
    const removeTouchListeners = () => {
        document.removeEventListener('touchmove', memoizedPreventDefault);
        document.removeEventListener('touchstart', memoizedPreventDefault);
    }

    // On touch event start
    const handleTouchStart = (e: React.TouchEvent<HTMLDivElement>, card: CardType) => {
        if (enemyDoingTurn) return;
        setDraggedCardMouse(false); // if mouse drag is happening disable it

        // store current target position because current target will have changed when the timeout ends
        const currentTarget = e.currentTarget;
        const currentTargetW = currentTarget.clientWidth;
        const currentTargetH = currentTarget.clientHeight;

        // wait small delay before touch drag event starts, can be canceled if they move their finger (ie. they wanted to scroll or select a card instead of a drag event)
        touchTimeout.current = setTimeout(() => {
            setDraggedCard(card);
            setParentDraggedCard(card);
            document.addEventListener('touchmove', memoizedPreventDefault, { passive: false });
            document.addEventListener('touchstart', memoizedPreventDefault, { passive: false });
            const touch = e.touches[0];
            setTouchPosition({ x: touch.clientX, y: touch.clientY });
            setDragCardPosition({ x: touch.clientX - (currentTargetW / 2), y: touch.clientY - (currentTargetH / 2) }); // - 50% with and height to make card center on touch
        }, 100);
    }

    // Touch moves
    const handleTouchMove = (e: React.TouchEvent<HTMLDivElement>) => {
        if (touchTimeout.current) { // clear touch start event if there is one (user didn't hold long enough to trigger drag event)
            clearTimeout(touchTimeout.current);
        }

        if (!draggedCard) return;

        // update positions:
        const touch = e.touches[0];
        setTouchPosition({ x: touch.clientX, y: touch.clientY });
        setDragCardPosition({ x: touch.clientX - (e.currentTarget.clientWidth / 2), y: touch.clientY - (e.currentTarget.clientHeight / 2) });
    };

    // touch or drag event end, send Custom dropEvent to targets.
    const handleTouchEnd = (e: React.TouchEvent<HTMLDivElement> | React.DragEvent<HTMLDivElement>) => {
        if (enemyDoingTurn) { // if enemy is somehow doing turn during this clear all states and cancel
            setDraggedCardMouse(false);
            setDraggedCard(undefined);
            setTouchPosition(undefined);
            setDragCardPosition(undefined);
            setParentDraggedCard(null);
            removeTouchListeners();
            return;
        };

        if (touchTimeout.current) { // end timeout early (if a card was tapped to select instead of hold to drag)
            clearTimeout(touchTimeout.current);
        }

        if (!touchPosition || !draggedCard) return; // if there is no ending position or dragged card

        const target = document.elementFromPoint(touchPosition.x, touchPosition.y); // get the target of the event (the card if touch or whats below it if drag)
        if (target) {
            // hide card to get element below:
            const divTarget = (target as HTMLDivElement);
            if (!draggedCardMouse) divTarget.style.visibility = "hidden"; // only needs to hide on touch events because they have pointer events enabled (mouse events dont)

            //get the first element below the target (where the card was dragged to)
            const belowTarget = document.elementFromPoint(touchPosition.x, touchPosition.y);

            if (!draggedCardMouse) divTarget.style.visibility = "visible"; // restore visibility to card

            if (belowTarget) { // if there is a target below, send cardDrop event
                const customEvent = new CustomEvent('cardDrop', {
                    bubbles: true,
                    cancelable: true,
                });

                belowTarget.dispatchEvent(customEvent);
            }
        }

        // clear drag and touch states and listeners:
        setDraggedCardMouse(false);
        setDraggedCard(undefined);
        setTouchPosition(undefined);
        setDragCardPosition(undefined);
        setParentDraggedCard(null);
        removeTouchListeners();
    }

    // effect for when card is dragging, update positon of dragged card
    useEffect(() => {
        if (!draggedCard) return;

        const handleDrag = (e: DragEvent) => {
            // update position
            setTouchPosition({ x: e.clientX, y: e.clientY });
            setDragCardPosition({ x: e.clientX - ((e.target as HTMLDivElement).clientWidth / 2), y: e.clientY - ((e.target as HTMLDivElement).clientHeight / 2) });
        };
        
        document.addEventListener('drag', handleDrag);

        return () => {
            // document.removeEventListener('cardDrop', handleCardDrop as EventListener);
            document.removeEventListener('drag', handleDrag);
        };
    }, [draggedCard]);

    return (
        <>
            <div id='cardHolder' onDragOver={(e) => e.preventDefault}>
                {hand.map(card => {
                    return (
                        <HandCard card={card} onCardSelect={onCardSelect} selectedCard={selectedCard} key={card.id} draggedCard={draggedCard} handleDragStart={handleDragStart} handleTouchStart={handleTouchStart} handleTouchEnd={handleTouchEnd} handleTouchMove={handleTouchMove} />
                    )
                })}
            </div>

            {(selectedCard && !draggedCard) && // display selected card:
                <div key={selectedCard.id} className={"display-card"} style={{ backgroundColor: (selectedCard.backgroundColor ?? 'burlywood') }} onClick={() => onCardSelect(selectedCard)}>
                    <button className='discardBtn' onClick={() => discardCard(selectedCard)}>Discard</button>
                    <img src={selectedCard.image} alt='Card Icon'></img>
                    <h4 className='dispCardTitle'>{selectedCard.title}</h4>
                    {selectedCard.specialActionDescription && (
                        <div className='specialDesc'>
                            {selectedCard.specialActionDescription}
                        </div>
                    )}
                    <div className='cardDesc'>
                        <p>{selectedCard.description}</p>
                    </div>
                    <div className='placableRows'>{selectedCard.rowTargetID?.map((row, index, arr) => {
                        if (row > 2) { // reduce 3-5 down to 0-2 because the rows are represented by the same symbols
                            row = Math.abs(5 - row);
                            if (arr.includes(row)) { // dont do duplicates
                                return null;
                            }
                        }

                        return (
                            <img key={row} className='rowTarget' src={row === 0 ? tallRow : row === 1 ? bushRow : grassRow} alt='rowIndicator' />
                        )
                    })}</div>
                    {(selectedCard.calculatedScore || selectedCard.score) > 0 &&
                        <div className='cardScore'>{selectedCard.calculatedScore || selectedCard.score}</div>
                    }
                </div>
            }

            {draggedCard && // display visual for dragged card (actual card being dragged is just hidden in the cardHolder, this needs to be outside for left and top to positon correctly)
                <div key={draggedCard.id + 'drag'}
                    className={'card dragged-card'}
                    style={{
                        backgroundColor: (draggedCard.backgroundColor ?? 'burlywood'),
                        left: dragCardPosition?.x + 'px',
                        top: dragCardPosition?.y + 'px',
                        pointerEvents: draggedCardMouse ? 'none' : 'auto', // pointer events are needed for touch events but will break drag events
                    }}
                >
                    <img src={draggedCard.image} alt='Card Icon' draggable='false'></img>
                    <h4>{draggedCard.title}</h4>
                    {(draggedCard.calculatedScore || draggedCard.score) > 0 &&
                        <div className='cardScore'>{draggedCard.calculatedScore || draggedCard.score}</div>
                    }
                </div>
            }
        </>
    );
};

const HandCard: React.FC<HandcardProps> = ({ card, onCardSelect, selectedCard, draggedCard, handleDragStart, handleTouchStart, handleTouchEnd, handleTouchMove }) => {
    const [rotation, setRotation] = useState({ X: 0, Y: 0 }); // rotation for 3d effect

    // mouse move listener, throttled to 100ms for performance
    const handleMouseMove = throttle((event) => {
        if (!event.currentTarget) { // make sure component has loaded
            return;
        }

        const rect = event.currentTarget.getBoundingClientRect(); // get element

        const x = event.clientX - rect.left - (event.currentTarget.offsetWidth / 2); // X position relative to center
        const y = -(event.clientY - rect.top - (event.currentTarget.offsetHeight / 2)); // Y position relative to center

        setRotation({ //*100 is magnitude of rotation, can be adjusted to change effect intensity
            X: parseFloat((y / event.currentTarget.offsetHeight / 2 * 100).toFixed(2)),
            Y: parseFloat((x / event.currentTarget.offsetWidth / 2 * 100).toFixed(2))
        });
    }, 100);


    const handleMouseLeave = () => {
        // reset rotation
        setRotation({
            X: 0,
            Y: 0
        });
    };

    return (
        <div key={card.id}
            className={`card ${selectedCard?.id === card.id ? "displayed" : ""}`}
            onClick={() => onCardSelect(card)}
            onMouseMove={handleMouseMove}
            onMouseLeave={handleMouseLeave}
            style={{
                backgroundColor: (card.backgroundColor ?? 'burlywood'),
                transform: `rotateX(${rotation.X}deg) rotateY(${rotation.Y}deg)`,
                opacity: (draggedCard?.id === card.id) ? '0' : '1',
            }}
            draggable="true"
            onTouchStart={(e) => handleTouchStart(e, card)}
            onDragStart={(e) => handleDragStart(e, card)}
            onDragEnd={handleTouchEnd}
            onTouchMove={(e) => handleTouchMove(e)}
            onTouchEnd={handleTouchEnd}
        >
            <img src={card.image} alt='Card Icon' draggable='false'></img>
            <h4>{card.title}</h4>
            {(card.calculatedScore || card.score) > 0 &&
                <div className='cardScore'>{card.calculatedScore || card.score}</div>
            }
        </div>
    )
}

export default Hand;