import React, { createContext, useState, FC, ReactNode } from 'react';

interface RoundContextType {
    round: number;
    setRound: React.Dispatch<React.SetStateAction<number>>;
}


export const RoundContext = createContext<RoundContextType | undefined>(undefined);

interface RoundProviderProps {
    children: ReactNode;
}

export const RoundProvider: FC<RoundProviderProps> = ({ children }) => {
    const [round, setRound] = useState(1);

    return (
        <RoundContext.Provider value={{ round, setRound }}>
            {children}
        </RoundContext.Provider>
    );
};