import React, { useEffect, useContext, useState, useRef, useCallback } from 'react';
import CardContext from './CardContext';
import { Card } from './types';
import { useNavigate, useLocation } from 'react-router-dom';
import '../styles/DeckBuilder.css';
import '../styles/Card.css';
import grassRow from './imgs/grassRow.png';
import bushRow from './imgs/bushRow.png';
import tallRow from './imgs/tallRow.png';

const requiredDeckSize = 15; // minimum deck size

const preventDefault = (e: TouchEvent) => { 
    e.preventDefault();
};

function DeckBuilder() {
    const context = useContext(CardContext);

    if (!context) {
        throw new Error('CardContext must be used within a CardProvider');
    }
    
    const navigate = useNavigate();
    const location = useLocation();
    
    const memoizedPreventDefault = useCallback((e: TouchEvent) => {
        preventDefault(e);
    }, []);
    
    
    useEffect(() => {
        window.history.pushState(null, document.title, window.location.href);
        const handleBeforeUnload = (event: Event) => {
            event.preventDefault(); // prevent window reload
        };

        const handleBack = (event: Event) => {
            window.history.pushState(null, document.title, window.location.href); // prevent page back button
        }

        window.addEventListener('popstate', handleBack);
        window.addEventListener('beforeunload', handleBeforeUnload);

        return () => {
            window.removeEventListener('popstate', handleBack);
            window.removeEventListener('beforeunload', handleBeforeUnload);
        };        
    }, [location]);

    // deck card states:
    const { userCards, deck } = context;
    const [selectedCards, setSelectedCards] = useState<Card[]>([]);
    const [selectedDeckCards, setSelectedDeckCards] = useState<Card[]>([]);
    const [detailedCard, setDetailedCard] = useState<Card>();

    // Drag states:
    const [draggedCard, setDraggedCard] = useState<Card>();
    const [touchPosition, setTouchPosition] = useState<{ x: number, y: number } | undefined>(undefined);
    const [dragCardPosition, setDragCardPosition] = useState<{ x: number, y: number } | undefined>(undefined);
    
    const ownedDropZoneRef = useRef<HTMLDivElement>(null);
    const deckDropZoneRef = useRef<HTMLDivElement>(null);
    const touchTimeout = useRef<NodeJS.Timeout | null>(null);


    const displayDetails = (card: Card) => {
        if (detailedCard?.id === card.id) {
            setDetailedCard(undefined) // toggle off detailed card
            setSelectedCards([]);
        } else {
            setSelectedCards([card]); // set selected to only this
            setDetailedCard(card);
        }
    }

    const displayDeckCardDetails = (card: Card) => {
        if (detailedCard?.id === card.id) {
            setDetailedCard(undefined) // toggle off detailed card
            setSelectedDeckCards([]);
        } else {
            setSelectedDeckCards([card]); // set selected to only this
            setDetailedCard(card);
        }
    }

    const selectCard = (card: Card) => {
        if (detailedCard !== undefined) { // no selections while detailed card is out
            return;
        }

        setSelectedCards(prevSelected => {
            if (prevSelected.includes(card)) { // toggle card in selection
                return prevSelected.filter(c => c.id !== card.id);
            } else {
                return [...prevSelected, card];
            }
        });
    }

    const selectDeckCard = (card: Card) => {
        if (detailedCard !== undefined) { // no selections while detailed card is out
            return;
        }

        setSelectedDeckCards(prevSelected => {
            if (prevSelected.includes(card)) { // toggle card in selection
                return prevSelected.filter(c => c.id !== card.id);
            } else {
                return [...prevSelected, card];
            }
        });
    }

    const handleMoveToDeck = () => {
        selectedCards.forEach(card => {
            deck.addCard(card);
        });

        setSelectedCards([]); // clear selection
        setDetailedCard(undefined); // clear details card
    } 

    const handleRemoveFromDeck = () => {
        selectedDeckCards.forEach(card => {
            deck.deckRemove(card);
        });

        setSelectedDeckCards([]); // clear selection and triger re-render
        setSelectedCards([]); // clear selection and triger re-render
        setDetailedCard(undefined); // clear details card
    } 

    const handleDragStart = (e: React.DragEvent<HTMLDivElement>, card: Card) => {
        // Remove the drag image by setting it to a transparent image:
        const img = new Image();
        img.src = 'data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///ywAAAAAAQABAAACAUwAOw=='; // Transparent image
        e.dataTransfer.setDragImage(img, 0, 0);
        
        setDraggedCard(card);
        setTouchPosition({x: e.clientX, y: e.clientY});
        setDragCardPosition({x: e.clientX - (e.currentTarget.clientWidth / 2), y: e.clientY - (e.currentTarget.clientHeight / 2)});
    };

        // Move out of deck drag/drop event:
    const handleDropOwned = (event: React.DragEvent<HTMLDivElement> | CustomEvent) => {
        if (!draggedCard) return;

        if (deck.cards.includes(draggedCard)) {
            deck.deckRemove(draggedCard);
            // setSelectedCards([]);
            // setSelectedDeckCards([]);
            setDetailedCard(undefined);
        }

        // setDraggedCard(undefined);
        // setTouchPosition(undefined);
        // setDragCardPosition(undefined);
        // setSelectedDeckCards([]); // clear selection and triger re-render
        // setSelectedCards([]); // clear selection and triger re-render
    }

    // Move to deck drag/drop event:
    const handleDropDeck = (event: React.DragEvent<HTMLDivElement> | CustomEvent) => {
        if (!draggedCard) return;

        if (!deck.cards.includes(draggedCard)) {
            deck.addCard(draggedCard);
            // setSelectedCards([]);
            setDetailedCard(undefined);
        }
        
        // setDraggedCard(undefined);
        // setTouchPosition(undefined);
        // setDragCardPosition(undefined);
        // setSelectedDeckCards([]); // clear selection and triger re-render
        // setSelectedCards([]); // clear selection and triger re-render
    }

    // remove prevent default listeners for touch
    const removeTouchListeners = () => {
        document.removeEventListener('touchmove', memoizedPreventDefault);
        document.removeEventListener('touchstart', memoizedPreventDefault);
    }

    const handleTouchStart = (e: React.TouchEvent<HTMLDivElement>, card: Card) => {
        // store current touch target width/height for use after delay
        const currentTargetW = e.currentTarget.clientWidth;
        const currentTargetH = e.currentTarget.clientHeight;
        touchTimeout.current = setTimeout(() => {
            setDraggedCard(card);
            document.addEventListener('touchmove', memoizedPreventDefault, {passive: false});
            document.addEventListener('touchstart', memoizedPreventDefault, {passive: false});
            const touch = e.touches[0];
            setTouchPosition({ x: touch.clientX, y: touch.clientY });
            setDragCardPosition({ x: touch.clientX - (currentTargetW / 2), y: touch.clientY - (currentTargetH / 2) });
        }, 100);
    }

    const handleTouchMove = (e: React.TouchEvent<HTMLDivElement>) => {
        if (touchTimeout.current) {
            clearTimeout(touchTimeout.current);
        }

        if (!draggedCard) return;

        const touch = e.touches[0];
        setTouchPosition({ x: touch.clientX, y: touch.clientY });
        setDragCardPosition({ x: touch.clientX - (e.currentTarget.clientWidth / 2), y: touch.clientY - (e.currentTarget.clientHeight / 2) });
    };

    const handleTouchEnd = (e: React.TouchEvent<HTMLDivElement> | React.DragEvent<HTMLDivElement>) => {
        if (touchTimeout.current) {
            clearTimeout(touchTimeout.current);
        }

        if (!touchPosition || !draggedCard) return;
        
        const target = document.elementFromPoint(touchPosition.x, touchPosition.y);
        if (target) {
            // hide card to get element below
            const divTarget = (target as HTMLDivElement);
            divTarget.style.visibility = "hidden";

            //get the first element below the target (the card being dragged)
            const belowTarget = document.elementFromPoint(touchPosition.x, touchPosition.y);

            divTarget.style.visibility = "visible"; // restore visibility to card

            if (belowTarget) {
                const customEvent = new CustomEvent('cardDrop', {
                    bubbles: true,
                    cancelable: true
                });
    
                belowTarget.dispatchEvent(customEvent);
            }
        }

        // clear states:
        setDraggedCard(undefined);
        setTouchPosition(undefined);
        setDragCardPosition(undefined);
        setSelectedDeckCards([]); // clear selection and triger re-render
        setSelectedCards([]); // clear selection and triger re-render
        removeTouchListeners();
    }
    
    // setup listeners for custom cardDrop events if a card starts dragging:
    useEffect(() => {
        if (!draggedCard) return;

        const handleCardDrop = (event: CustomEvent) => {
            if (!draggedCard) return;

            const target = event.target as HTMLDivElement;
            if (target.closest('#ownedCards') === ownedDropZoneRef.current) {
                handleDropOwned(event);
            } else if (target.closest('#deckContainer') === deckDropZoneRef.current) {
                handleDropDeck(event);
            }
        };

        const handleDrag = (e: DragEvent) => {
            setTouchPosition({x: e.clientX, y: e.clientY});
            setDragCardPosition({x: e.clientX - ((e.target as HTMLDivElement).clientWidth / 2), y: e.clientY - ((e.target as HTMLDivElement).clientHeight / 2)});
        };
    
        document.addEventListener('cardDrop', handleCardDrop as EventListener);
        document.addEventListener('drag', handleDrag);
        
        return () => {
            document.removeEventListener('cardDrop', handleCardDrop as EventListener);
            document.removeEventListener('drag', handleDrag);
        };
    }, [draggedCard]);

    return (
        <div id="deckBuilderContainer">
            <div id='ownedCards' className={(draggedCard && deck.cards.includes(draggedCard)) ? 'draggableTarget' : ''} 
            ref={ownedDropZoneRef}
            onDragOver={(e) => e.preventDefault()}
            >
                <h1>Owned Cards</h1>
                <div className='cardList'>
                    {userCards.getOwnedCards().sort((a: Card, b: Card) => (a.title < b.title) ? -1 : 1).map(card =>
                        {
                            if (deck.cards.includes(card)) { //dont show already added cards
                                return null;
                            }

                            return (
                                <div key={card.id} 
                                    className={`${(detailedCard && detailedCard.id === card.id) ? 'deck-display-card' : 'card'} ${selectedCards.includes(card) ? 'selected' : ''} ${(draggedCard && draggedCard.id === card.id) ? 'dragged-card' : ''}`} 
                                    onClick={() => selectCard(card)} 
                                    onContextMenu={(e) => {e.preventDefault(); displayDetails(card);}} 
                                    style={{
                                        backgroundColor: (card.backgroundColor ?? 'burlywood'),
                                        left: (draggedCard && draggedCard.id === card.id) ? dragCardPosition?.x + 'px' : '',
                                        top: (draggedCard && draggedCard.id === card.id) ? dragCardPosition?.y + 'px' : '',
                                    }}
                                    draggable="true"
                                    onDragStart={(e) => handleDragStart(e, card)}
                                    onDragEnd={handleTouchEnd}
                                    onTouchStart={(e) => handleTouchStart(e, card)}
                                    onTouchMove={(e) => handleTouchMove(e)}
                                    onTouchEnd={handleTouchEnd}
                                >
                                    <img src={card.image} alt='Card Icon' draggable='false'/>
                                    <h4 className={`${(detailedCard && detailedCard.id === card.id) ? 'dispCardTitle' : ''}`}>{card.title}</h4>
                                    {(detailedCard && detailedCard.id === card.id) ?
                                        <>
                                            <div className='closeDetails' onClick={(e) => {e.stopPropagation(); displayDetails(card);}}>X</div>
                                            {card.specialActionDescription && (
                                                <div className='specialDesc'>
                                                    {card.specialActionDescription}
                                                </div>
                                            )}
                                            <div className='cardDesc'>
                                                <p>{card.description}</p>
                                            </div>
                                            <div className='placableRows'>{card.rowTargetID?.map((row, index, arr) => {
                                                if (row > 2) {
                                                    row = Math.abs(5-row);
                                                    if (arr.includes(row)) { // dont do duplicates
                                                        return null;
                                                    }
                                                }

                                                return (
                                                    <img key={row} className='rowTarget' src={row === 0 ? tallRow : row === 1 ? bushRow : grassRow} alt='rowIndicator'/>
                                                )
                                            })}</div>
                                            <button className='addCardBtn' onClick={() => handleMoveToDeck()}>Add To Deck</button>
                                        </>
                                        :
                                        <div className='infoDetails' onClick={(e) => { e.stopPropagation(); displayDetails(card); }}>i</div>
                                    }
                                    {card.score > 0 &&
                                        <div className='cardScore'>{card.score}</div>
                                    }
                                </div>
                            );
                    })}
                </div>
            </div>
            <div id="deckIndicators">
                <button id='addAction' className={`deckActionBtn ${selectedCards.length > 0 && detailedCard === undefined ? '' : 'disabled'}`} onClick={selectedCards.length > 0 && detailedCard === undefined ? () => handleMoveToDeck() : () => {}}>Add To Deck<br/></button>
                <button id='removeAction' className={`deckActionBtn ${selectedDeckCards.length > 0 && detailedCard === undefined ? '' : 'disabled'}`} onClick={selectedDeckCards.length > 0 && detailedCard === undefined ? () => handleRemoveFromDeck() : () => {}}>Remove From Deck<br/></button>
            </div>
            <div id="deckContainer" 
            ref={deckDropZoneRef}
            onDragOver={(e) => e.preventDefault()}
            >
                <div id="deck" className={(draggedCard && !deck.cards.includes(draggedCard)) ? 'draggableTarget' : ''}>
                    <h1>Deck</h1>
                    <div className='cardList'>
                        {deck.getDeck().sort((a: Card, b: Card) => (a.title < b.title) ? -1 : 1).map(card =>
                            <div key={card.id} 
                                className={`${(detailedCard && detailedCard.id === card.id) ? 'deck-display-card' : 'card'} ${selectedDeckCards.includes(card) ? 'selected' : ''} ${(draggedCard && draggedCard.id === card.id) ? 'dragged-card' : ''}`} 
                                onClick={() => selectDeckCard(card)} 
                                onContextMenu={(e) => {e.preventDefault(); displayDeckCardDetails(card);}} 
                                style={{
                                    backgroundColor: (card.backgroundColor ?? 'burlywood'),
                                    left: (draggedCard && draggedCard.id === card.id) ? dragCardPosition?.x + 'px' : '',
                                    top: (draggedCard && draggedCard.id === card.id) ? dragCardPosition?.y + 'px' : '',
                                }}
                                draggable="true"
                                onDragStart={(e) => handleDragStart(e, card)}
                                onDragEnd={handleTouchEnd}
                                onTouchStart={(e) => handleTouchStart(e, card)}
                                onTouchMove={(e) => handleTouchMove(e)}
                                onTouchEnd={handleTouchEnd}
                            >
                                <img src={card.image} alt='Card Icon' draggable='false'/>
                                <h4 className={`${(detailedCard && detailedCard.id === card.id) ? 'dispCardTitle' : ''}`}>{card.title}</h4>
                                {(detailedCard && detailedCard.id === card.id) ?
                                    <>
                                        <div className='closeDetails' onClick={(e) => {e.stopPropagation(); displayDeckCardDetails(card);}}>X</div>
                                        {card.specialActionDescription && (
                                            <div className='specialDesc'>
                                                {card.specialActionDescription}
                                            </div>
                                        )}
                                        <div className='cardDesc'>
                                            <p>{card.description}</p>
                                        </div>
                                        <div className='placableRows'>{card.rowTargetID?.map((row, index, arr) => {
                                            if (row > 2) {
                                                row = Math.abs(5-row);
                                                if (arr.includes(row)) { // dont do duplicates
                                                    return null;
                                                }
                                            }

                                            return (
                                                <img key={row} className='rowTarget' src={row === 0 ? tallRow : row === 1 ? bushRow : grassRow} alt='rowIndicator'/>
                                            )
                                        })}</div>
                                        <button className='addCardBtn' onClick={() => handleRemoveFromDeck()} style={{backgroundColor: 'red'}}>Remove From Deck</button>
                                    </>
                                    :
                                    <div className='infoDetails' onClick={(e) => { e.stopPropagation(); displayDeckCardDetails(card); }}>i</div>
                                }
                                {card.score > 0 &&
                                    <div className='cardScore'>{card.score}</div>
                                }
                            </div>
                        )}
                    </div>
                </div>
                <div id="nextRoundContainer">
                    <p id="deckSizeIndicator">Deck Size: {deck.cards.length} {deck.cards.length < requiredDeckSize ? '/' + requiredDeckSize : ''}</p>
                    <button id="nextRoundBtn" className={deck.cards.length < requiredDeckSize ? 'disabled' : ''} onClick={() => {
                        if (deck.cards.length >= requiredDeckSize) {
                            navigate('/game')
                        }
                    }}>Next Round &#9658;</button>
                </div>
            </div>
        </div>
        
    );
}

export default DeckBuilder;