import { Card } from "./types";
import { AllCards } from "./AllCards";
import { getCounter, incrementCounter } from "./counter";
import cloneDeep from 'lodash/cloneDeep';

    
const startingDeck = [
    [21, 3], // Mountain Maple
    [22, 3], // Junegrass
    [23, 2], // Honeycrisp
    [0, 2], // American Basswood
    [1, 2], // Eastern Red Ceader
    [2, 1], // Swiss Stone Pine
    [3, 1], // Ironwood
    [5, 1], // Logging Company
    [6, 1], // Transplant
    [7, 1], // Extra sun
    [10, 1], // Supress
    [11, 1], // Supress Mid
    [12, 1], // Supress Back
    [13, 1], // Weaken
    [14, 2], // Clear Supress
    [16, 1], // Ohio Buckeye
    // [17, 1], // mulberry
    [18, 1], // senna
    // [19, 6], // blueberry
    // [20, 1], // prince oak
    // [24, 2], // Amur Maple 
    // [25, 1], // greenhouse
];

class OwnedCards {
    ownedCards: Card[]; // map with card and quantity

    constructor() {
        this.ownedCards = [];
        for (const val of startingDeck) {
            const key: number = val[0];
            const num: number = val[1];

            for (let i = 0; i < num; i++) {
                this.addCard(AllCards[key].card);
            }
        }

        // let index = 0;
        // AllCards.forEach(item => {
        //     index++;
        //     if (index >= 20) {
        //         return;
        //     }
        //     for (let i = 0; i < item.quantity; i++) {
        //         this.addCard(item.card);
        //     }
        // });
    }

    addCard(card: Card): void {
        const newCard = cloneDeep(card);
        newCard.id = getCounter(); // assign global ID and increment
        incrementCounter();
        this.ownedCards.push(newCard);
    }

    getOwnedCards(): Card[] {
        return this.ownedCards;
    }


    // Generate a random selection of cards that the user does not currently that improve as the rounds go on
    generateCardChoices(nCards: number, round: number): Card[] | null {
        let selectedCards: Card[] = [];

        let cardPullChance: number[] = [1, 0, 0, 0]; // chance of pulling card in each tier 1 2 3 4

        if (round > 2) {
            cardPullChance[1] = Math.min((round*15 / 2) / 100, 0.4);
            cardPullChance[0] -= cardPullChance[1];
        } 
        
        if (round > 4) {
            cardPullChance[2] = Math.min((round*15 / 4) / 100, 0.3);
            cardPullChance[1] -= cardPullChance[2]*0.4;
            cardPullChance[0] -= cardPullChance[2]*0.6;
        }

        if (round > 8) {
            cardPullChance[3] = Math.min((round*15 / 8) / 100, 0.2);
            cardPullChance[2] -= cardPullChance[3]*0.2;
            cardPullChance[1] -= cardPullChance[3]*0.3;
            cardPullChance[0] -= cardPullChance[3]*0.5;
        }

        const calculateThresholds = (oddsList: number[]): number[] => {
            let thresholds: number[] = [];
            
            let total = 0;

            for (let i = 0; i < oddsList.length-1; i++) {
                total += oddsList[i];
                thresholds.push(total);
            }

            thresholds.push(1); // last threshold is always 1

            return thresholds;
        };

        let cardPullThresholds = calculateThresholds(cardPullChance);

        let cardQualityList: any[][][] = [[], [], [], []];
        AllCards.forEach(item => {
            const ownedLen = this.ownedCards.filter(card => card.title === item.card.title).length

            const updatedQuantity = item.quantity-ownedLen
            if (updatedQuantity > 0) { // add card if there is still some left to get
                cardQualityList[item.quality-1].push([item.card, updatedQuantity]);
                // console.log("Card left to get: " + item.card.title + " " + updatedQuantity);
            }
        });

        // filter out any empty arrays and redistribute chances:
        for (let i = 0; i < cardQualityList.length; i++) {
            if (cardQualityList[i].length === 0) { // empty row
                const chanceRemoved: number = cardPullChance.splice(i, 1)[0];
                if (i < cardPullChance.length) {
                    cardPullChance[i] += chanceRemoved;
                } else {
                    cardPullChance[i-1] += chanceRemoved;
                }

                // redestribute thresholds
                cardPullThresholds = calculateThresholds(cardPullChance);
            }
        }

        cardQualityList = cardQualityList.filter(subArray => subArray.length > 0);

        let cardCount = 0;
        while (selectedCards.length < nCards && cardQualityList && cardQualityList.length > 0) {
            if (cardPullChance.reduce((prevChance, newChance) => prevChance+newChance) === 0) { // no more cards can be selected
                break;
            }

            const random = Math.random(); // random card selection
           
            let index = 0;
            for (const threshold of cardPullThresholds) {
                if (random <= threshold) { // select card at this threshold
                    if (!cardQualityList[index]) {
                        console.log("no threshold??");
                        break;
                    }; 
                    const randCard = Math.floor(Math.random()*cardQualityList[index].length);
                    const selectedCard = cloneDeep(cardQualityList[index][randCard][0]);
                    selectedCard.id = cardCount;
                    cardCount++;
                    selectedCards.push(selectedCard);
                    
                    cardQualityList[index][randCard][1] -= 1;
                    if (cardQualityList[index][randCard][1] === 0) {
                        cardQualityList[index].splice(randCard, 1);
                        if (cardQualityList[index].length === 0) {
                            // fill in thresholds and remove
                            const chanceRemoved: number = cardPullChance.splice(index, 1)[0];
                            if (index < cardPullChance.length) {
                                cardPullChance[index] += chanceRemoved;
                            } else {
                                cardPullChance[index-1] += chanceRemoved;
                            }

                            // redestribute thresholds
                            cardPullThresholds = calculateThresholds(cardPullChance);
                            cardQualityList.splice(index, 1);
                        }
                    }
                    break;
                }
                
                index++;
            };
        }

        return selectedCards;
    }
}

export default OwnedCards;