import { Card, Row } from "./types";
import { AllCards } from "./AllCards";
import { getCounter, incrementCounter } from "./counter";
import cloneDeep from 'lodash/cloneDeep';

const handSize = 5;

class Enemy {
    deck: Card[]; // enemy deck
    hand: Card[]; // enemy hand

    constructor() {
        this.deck = [];
        this.hand = [];
        this.generateDeck(0);
    }

    generateDeck(round: number): void {
        // reset hand and deck
        this.hand = [];
        this.deck = [];

        // generate enemy deck with a smaller size as time goes on
        const deckSizeTarget = 15+Math.floor(Math.random()*Math.max((10-round), 0)) + Math.floor(Math.random() * 5);
        // const cardQualityTarget = deckSizeTarget + Math.floor(Math.random() * round) + Math.floor(round/2);
        let cardPullChance: number[] = [1, 0, 0, 0]; // chance of pulling card in each tier 1 2 3 4

        if (round > 3) {
            cardPullChance[1] = Math.min((round*15 / 2) / 100, 0.3);
            cardPullChance[0] -= cardPullChance[1];
        } 
        
        if (round > 5) {
            cardPullChance[2] = Math.min((round*15 / 4) / 100, 0.15);
            cardPullChance[1] -= cardPullChance[2]*0.4;
            cardPullChance[0] -= cardPullChance[2]*0.6;
        }

        if (round > 10) {
            cardPullChance[3] = Math.min((round*15 / 8) / 100, 0.1);
            cardPullChance[2] -= cardPullChance[3]*0.2;
            cardPullChance[1] -= cardPullChance[3]*0.3;
            cardPullChance[0] -= cardPullChance[3]*0.5;
        }

        // console.log("Chances: " + cardPullChance);

        // turns percentage odds into a threshold list between 0 and 1.
        const calculateThresholds = (oddsList: number[]): number[] => {
            let thresholds: number[] = [];
            
            let total = 0;

            for (let i = 0; i < oddsList.length-1; i++) {
                total += oddsList[i];
                thresholds.push(total);
            }

            thresholds.push(1); // last threshold is always 1

            return thresholds;
        };

        // convert card pull chance to thresholds
        let cardPullThresholds = calculateThresholds(cardPullChance);

        // console.log("Thresholds: " + cardPullThresholds);

        // put all possible cards into a list with quantity:
        let cardQualityList: any[][][] = [[], [], [], []];
        AllCards.forEach(item => {
            cardQualityList[item.quality-1].push([item.card, item.quantity]);
        });

        while (this.deck.length < deckSizeTarget) {
            if (cardPullChance.reduce((prevChance, newChance) => prevChance+newChance) === 0) { // no more cards can be selected
                break;
            }

            const random = Math.random(); // random card selection
           
            let index = 0;
            for (const threshold of cardPullThresholds) {
                if (random <= threshold) { // select card at this threshold
                    // console.log("Selecting card from threshold: " + index);
                    const randCard = Math.floor(Math.random()*cardQualityList[index].length);
                    this.addCard(cardQualityList[index][randCard][0]);
                    cardQualityList[index][randCard][1] -= 1;
                    if (cardQualityList[index][randCard][1] === 0) {
                        cardQualityList[index].splice(randCard, 1);
                        if (cardQualityList[index].length === 0) {
                            // fill in thresholds and remove
                            const chanceRemoved: number = cardPullChance.splice(index, 1)[0];
                            if (index < cardPullChance.length) {
                                cardPullChance[index] += chanceRemoved;
                            } else {
                                cardPullChance[index-1] += chanceRemoved;
                            }
                            // console.log("Distributed chances: " + cardPullChance);
                            cardPullThresholds = calculateThresholds(cardPullChance);
                            cardQualityList.splice(index, 1);
                        }
                    }
                    break;
                }
                
                index++;
            };
        }
        

        // TODO: select at least some 1 quality cards or basic cards as level goes up. Avoid repeats of some cards
        // TODO: maybe draft up some preset decks with some randomization on top to make more consistent enemyes?

        for (let i = 0; i < 5; i++) {
            this.drawCard(); // draw 5 cards
        }
    }

    selectTurnCard(rows: Row[], roundsRemaining: number): [Card | null, number | null, number | null] {
        if (this.hand.length === 0) { // skip enemy turn, out of cards
            return [null, 0, 0];
        }

        //calculate best moves out of all cards in hand
        let bestScore = -1;
        let bestCard = this.hand[0];
        let selectedRow = null;
        let selectedIndex = null;
        this.hand.forEach(card => {
            if (card.calcEnemyMoveScore) {
                let result = card.calcEnemyMoveScore(card, rows, this.hand, roundsRemaining);

                if (result[0] > bestScore) {
                    bestScore = result[0];
                    bestCard = card;
                    // Set values to null in new best card doesnt use them:
                    selectedRow = null;
                    selectedIndex = null;
                    if (card.selectsOtherCards) {
                        selectedRow = result[1] || 0;
                        selectedIndex = result[2] || 0;
                    } else if (result[1]) { // cards that can be placed in multiple rows
                        selectedRow = result[1];
                    }
                }
            }
        });

        //Skip if action is negative TODO: discard card
        if (bestScore < 0) {
            this.hand = this.hand.splice(0, 4);
            this.drawCard();
            return [null, 0, 0];
        }

        return [bestCard, selectedRow, selectedIndex];
    }

    useTurnCard(rows: Row[], card: Card, selectedRow: number | null, selectedIndex: number | null, turn: number): Row[] {
        // use the enemy selected card:
        if (card.selectsOtherCards) {
            console.log(selectedRow, selectedIndex);
            if (card.selectCardAction && selectedRow !== null && selectedIndex !== null) {
                [rows, this.hand] = card.selectCardAction(card, selectedRow, selectedIndex, rows, this.hand, turn);
            }
        } else if (card.enemyRowTargetID) {
            rows = this.placeEnemyCard(rows, card, selectedRow || card.enemyRowTargetID[0]); // selected row or default
        }

        // Draw a new card:
        if (this.hand.length < handSize) {
            this.drawCard();
        }

        return rows;
    }

    placeEnemyCard(rows: Row[], card: Card, rowId: number): Row[] {
        // Find the row and add the card to it
        rows = rows.map(row => { // temp rows to be passed along and updated
            if (row.id === rowId) {
                return { ...row, cards: [...row.cards, card] };
            }
            return row;
        });

        card.placedRow = rowId; // updated placed row

        this.hand = this.hand.filter(handCard => handCard.id !== card.id); // remove this card from the enemy hand
        
        // card place actions
        if (card.enemyPlaceAction) { // if card has different behavior for enemies use that, otherwise default
            [rows, this.hand] = card.enemyPlaceAction(card, rows, this.hand);
        } else if (card.placeAction) {
            [rows, this.hand] = card.placeAction(card, rows, this.hand);
        }

        return rows;
    }

    drawCard(): void {
        if (this.deck.length === 0) { // deck empty
            return;
        }

        const randIndex = Math.floor(Math.random() * this.deck.length);
        const drawnCard = this.deck[randIndex];
        this.hand.push(drawnCard);
        this.removeCard(drawnCard); // remove drawn card from in use deck
        return;
    }

    addCard(card: Card): void {
        const newCard = cloneDeep(card);
        newCard.id = getCounter(); // assign global ID and increment
        //console.log("Enemy Cards:" + getCounter());
        incrementCounter();
        this.deck.push(newCard);
    }

    removeCard(card: Card) {
        const index = this.deck.findIndex(c => c.id === card.id);
        if (index !== -1) {
            this.deck.splice(index, 1);
        }
    }

    getDeck(): Card[] {
        return this.deck;
    }
}

export default Enemy;